const slug=document.body.dataset.course;const course=C[slug];const nav=document.getElementById('moduleNav'),content=document.getElementById('lessonContent');const key='skillspring-'+slug+'-progress';let progress=JSON.parse(localStorage.getItem(key)||'{}');let active=Number(localStorage.getItem(key+'-active')||0);let passed=JSON.parse(localStorage.getItem(key+'-passed')||'{}');let finalView=false;const SSA=window.SkillSpringAssessment;
document.title=course.name+' · SkillSpring';
document.getElementById('courseName').textContent=course.name;document.getElementById('courseIntro').textContent=course.intro;
function update(){const done=Object.values(progress).filter(Boolean).length,pct=Math.round(done/course.modules.length*100);document.getElementById('progressBar').style.width=pct+'%';document.getElementById('progressText').textContent=pct+'% complete';document.getElementById('lessonCount').textContent=done+' of '+course.modules.length+' modules completed'}
function render(){active=Math.max(0,Math.min(course.modules.length-1,active));localStorage.setItem(key+'-active',active);nav.innerHTML=course.modules.map((m,i)=>'<button class="module-link '+(i===active?'active ':'')+(progress[i]?'done':'')+'" data-i="'+i+'"><span class="num">'+(progress[i]?'✓':String(i+1).padStart(2,'0'))+'</span><span>'+m[0]+'</span></button>').join('')+'<button class="module-link final-link '+(finalView?'active':'')+'" data-final="1"><span class="num">★</span><span>Final assessment</span></button>';if(finalView){SSA.finalAssessment(content,course.modules.map(x=>({lesson:x[0],question:x[5],correct:x[6],wrong:x[7]})),key+'-final',course.name,slug);update();return}const m=course.modules[active];const o=SSA.options([m[6],...m[7]],slug+':'+active);content.innerHTML='<div class="lesson"><div class="eyebrow">MODULE '+(active+1)+' OF '+course.modules.length+'</div><h2>'+m[0]+'</h2><h3>Understand the concept</h3><p>'+m[1]+'</p><h3>Worked example</h3><div class="code"><button class="copy">Copy</button><pre></pre></div><div class="callout">'+m[3]+'</div><div class="task"><h3>Practice task</h3><p>'+m[4]+'</p><p>Write your solution in your own editor or the matching practice tool. Test normal cases and edge cases. Keep your work in a GitHub repository as you progress.</p></div><div class="quiz"><h3>Knowledge check</h3><p>'+m[5]+'</p>'+o.labels.map((v,i)=>'<label><input type="radio" name="answer" value="'+i+'"> '+String.fromCharCode(65+i)+'. '+v+'</label>').join('')+'<button id="check">Check answer</button><div class="feedback" id="feedback"></div></div><div class="lesson-actions"><button class="secondary" id="prev" '+(active===0?'disabled':'')+'>← Previous</button><button class="complete" id="done">'+(progress[active]?'✓ Completed · Mark incomplete':'Mark complete')+'</button><button class="primary" id="next">'+(active===course.modules.length-1?'Final assessment →':'Next module →')+'</button></div></div>';const pre=content.querySelector('pre');pre.textContent=m[2];content.querySelector('.copy').onclick=()=>navigator.clipboard?.writeText(pre.textContent);document.getElementById('prev').onclick=()=>{active--;render()};document.getElementById('next').onclick=()=>{if(active<course.modules.length-1)active++;else finalView=true;render();window.scrollTo(0,0)};document.getElementById('done').onclick=()=>{if(!progress[active]&&!passed[active]){document.getElementById('feedback').textContent='Pass the knowledge check above before marking this module complete.';return}progress[active]=!progress[active];localStorage.setItem(key,JSON.stringify(progress));render()};document.getElementById('check').onclick=()=>{const choice=content.querySelector('input[name=answer]:checked');document.getElementById('feedback').textContent=!choice?'Choose an answer.':Number(choice.value)===o.correct?(passed[active]=true,localStorage.setItem(key+'-passed',JSON.stringify(passed)),'Correct! '+m[3]):'Not quite. Review the concept and try again. '+m[3]};update()}
nav.addEventListener('click',e=>{const f=e.target.closest('[data-final]');if(f){finalView=true;render();return}const b=e.target.closest('[data-i]');if(b){finalView=false;active=Number(b.dataset.i);render()}});document.getElementById('resetProgress').onclick=()=>{if(confirm('Reset progress for this course on this device?')){progress={};passed={};finalView=false;active=0;localStorage.removeItem(key);localStorage.removeItem(key+'-passed');localStorage.removeItem(key+'-final');render()}};render();